'use client'
import { X } from 'lucide-react'
import { useRef, type ReactNode } from 'react'
import { useControllable } from '@/hooks/useControllable'
import { useSheet } from '@/hooks/useSheet'

// A panel at the right edge over the page (the docs panel, console2.css .v2-docs): 420px (the screen on a phone), a
// hairline at its edge, the 48px bar with the title and a close button, then the body (20px 26px 48px), scrolling on
// its own. It is modal: the page dims to 16% under it and stays inert. It comes in 16px from the right over 220ms on
// the strong ease-out and leaves in 160ms; Escape closes it at once; focus returns to what opened it.
export interface SheetProps {
  title: string
  description?: string
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Controls in the bar, before the close button (Vue's `bar` slot). */
  bar?: ReactNode
  /** Buttons at the foot (Vue's `foot` slot). */
  foot?: ReactNode
  children?: ReactNode
}

export function Sheet({ title, description, open: given, defaultOpen = false, onOpenChange, bar, foot, children }: SheetProps) {
  const [open, setOpen] = useControllable(given, defaultOpen, onOpenChange)
  const dialog = useRef<HTMLDialogElement | null>(null)
  const { shown, onCancel, onClick } = useSheet(dialog, open, setOpen)
  return (
    <dialog data-ds="sheet" ref={dialog} className="ds-sheet" data-shown={shown || undefined} aria-label={title} tabIndex={-1} onCancel={onCancel} onClick={onClick}>
      <style href="ds-sheet" precedence="ds">{css}</style>
      <div className="flex h-bar shrink-0 items-center gap-1 border-b border-edge pr-2 pl-6.5">
        <h2 className="min-w-0 flex-1 truncate type-ui-strong">{title}</h2>
        {bar}
        <button type="button" className="inline-flex size-control-sm shrink-0 cursor-pointer items-center justify-center border border-transparent text-fg-soft transition-[color,border-color] duration-120 ease-standard hover:border-edge-strong hover:text-fg focus-visible:outline-2 focus-visible:outline-edge-focus max-md:size-control-touch" aria-label="close" onClick={() => setOpen(false)}><X size={14} strokeWidth={1.5} /></button>
      </div>
      <div className="fade-y min-h-0 flex-1 overflow-y-auto overscroll-contain px-6.5 pt-5 pb-12" data-sheet-body="">
        {description && <p className="mb-4 type-ui text-fg-soft">{description}</p>}
        {children}
      </div>
      {foot && <div className="flex shrink-0 justify-end gap-2 border-t border-edge px-6.5 py-3">{foot}</div>}
    </dialog>
  )
}

export default Sheet

const css = `
.ds-sheet { position: fixed; inset: 0 0 0 auto; width: min(var(--ds-layout-sheet), 100vw); height: 100dvh; max-width: none; max-height: none; margin: 0; padding: 0; border: 0; border-left: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface); color: var(--ds-color-fg); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); opacity: 0; transform: translateX(16px); transition: opacity var(--ds-duration-glide) var(--ds-easing-out), transform var(--ds-duration-glide) var(--ds-easing-out); }
.ds-sheet[open] { display: flex; flex-direction: column; }
.ds-sheet:focus { outline: none; }
.ds-sheet[data-shown] { opacity: 1; transform: none; transition-duration: var(--ds-duration-settle); }
.ds-sheet::backdrop { background: var(--ds-color-scrim-light); opacity: 0; transition: opacity var(--ds-duration-glide) var(--ds-easing-out); }
.ds-sheet[data-shown]::backdrop { opacity: 1; transition-duration: var(--ds-duration-settle); }
@media (prefers-reduced-motion: reduce) { .ds-sheet { transform: none; } }
`

'use client'
import { useEffect, useRef, useState, type RefObject } from 'react'
import { firstFocusable } from '@/hooks/usePopover'

/**
 * A native modal dialog that slides (Sheet, Drawer): showModal keeps focus inside and the page inert; the panel and its
 * scrim come in on `data-shown` and leave on its removal, closing once the exit transition has run (read from CSS, so
 * reduced motion and the tokens decide). Escape closes at once (keyboard actions don't animate); the scrim closes it;
 * focus returns to what opened it. Focus starts on the first control in `[data-autofocus]` or the body, else the panel.
 * `open` and `setOpen` are the component's controllable open state (Vue's v-model:open).
 */
export function useSheet(dialog: RefObject<HTMLDialogElement | null>, open: boolean, setOpen: (open: boolean) => void, options: { dismissable?: () => boolean } = {}) {
  const [shown, setShownState] = useState(false)
  const isShown = useRef(false)
  const setShown = (v: boolean) => {
    isShown.current = v
    setShownState(v)
  }
  const returnTo = useRef<HTMLElement | null>(null)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const exiting = useRef(false)

  function exitMs(el: HTMLElement) {
    const parts = getComputedStyle(el).transitionDuration.split(',').map(s => Number.parseFloat(s) * (s.trim().endsWith('ms') ? 1 : 1000))
    return Math.max(0, ...parts.filter(n => !Number.isNaN(n)))
  }
  async function show() {
    const d = dialog.current
    if (!d || d.open) return
    clearTimeout(timer.current)
    returnTo.current = document.activeElement instanceof HTMLElement ? document.activeElement : null
    d.showModal()
    const start = d.querySelector<HTMLElement>('[data-autofocus]') ?? firstFocusable(d.querySelector<HTMLElement>('[data-sheet-body]'))
    ;(start ?? d).focus({ preventScroll: true })
    // One frame at the closed state, so the transition has somewhere to start.
    await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)))
    setShown(true)
  }
  function finish() {
    dialog.current?.close()
    returnTo.current?.focus({ preventScroll: true })
    returnTo.current = null
  }
  function hide(instant = false) {
    const d = dialog.current
    if (!d?.open) return
    if (instant) {
      setShown(false)
      return finish()
    }
    // ds-latency: the dialog stays in the top layer until its exit has played (timed once the panel has re-rendered
    // without data-shown, as Vue's nextTick, so its exit duration is the one read).
    if (!isShown.current) timer.current = setTimeout(finish, exitMs(d))
    else {
      exiting.current = true
      setShown(false)
    }
  }
  useEffect(() => {
    const d = dialog.current
    if (shown || !exiting.current || !d) return
    exiting.current = false
    timer.current = setTimeout(finish, exitMs(d))
  }, [shown]) // eslint-disable-line react-hooks/exhaustive-deps

  // Vue's watch(open) and onMounted: show when it opens (or starts open), hide when it closes.
  const mounted = useRef(false)
  useEffect(() => {
    if (!mounted.current) {
      mounted.current = true
      if (open) void show()
      return
    }
    if (open) void show()
    else hide()
  }, [open]) // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => () => clearTimeout(timer.current), [])

  /** Escape: at once, no exit motion. */
  function onCancel(event: { preventDefault: () => void }) {
    event.preventDefault()
    if (options.dismissable && !options.dismissable()) return
    setOpen(false)
    hide(true)
  }
  /** A press on the scrim lands on the dialog element itself. */
  function onClick(event: { target: EventTarget | null }) {
    if (event.target === dialog.current && (!options.dismissable || options.dismissable())) setOpen(false)
  }
  return { shown, onCancel, onClick, hide }
}

'use client'
import { useCallback, useRef, useState } from 'react'

// Vue's defineModel in React: a value that is controlled when the caller passes it (value + onValueChange, as Radix
// does) and kept inside otherwise (defaultValue). setValue calls onChange either way.
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
	const [inner, setInner] = useState<T>(defaultValue)
	const controlled = value !== undefined
	const current = controlled ? value : inner
	const ref = useRef(onChange)
	ref.current = onChange
	const set = useCallback((next: T) => {
		if (!controlled) setInner(next)
		ref.current?.(next)
	}, [controlled])
	return [current, set] as const
}
